+const { NativeModules } = require("react-native");
+
+function getConfigFromNative() {
+  const NativeConfigModule = require("./codegen/NativeConfigModule").default;
+  if (NativeConfigModule != null) {
+    return NativeConfigModule.getConfig().config;
+  }
+  const legacy = NativeModules.RNCConfigModule;
+  if (legacy == null) {
+    throw new Error(
+      "[react-native-config] Native module RNCConfigModule is not available. " +
+        "Rebuild the app after installing dependencies."
+    );
+  }
+  const payload = legacy.getConfig();
+  if (payload != null && typeof payload === "object" && "config" in payload) {
+    return payload.config;
