/**
 * Post-registration bootstrap: globals, Firebase background handler, console.
 * Loaded after AppRegistry so a failure here does not block registration.
 *
 * @format
 */

import {decode, encode} from 'base-64';

if (!global.btoa) {
  global.btoa = encode;
}
if (!global.atob) {
  global.atob = decode;
}

import constants from '@constants';

void constants;

import messaging from '@react-native-firebase/messaging';

messaging().setBackgroundMessageHandler(async remoteMessage => {
  console.log(`Message from remote: ${remoteMessage}`);
});

if (
  process.env.NODE_ENV === 'production' &&
  typeof global !== 'undefined' &&
  !global.$fake
) {
  global.console = {
    info: () => {},
    log: () => {},
    warn: () => {},
    debug: () => {},
    error: () => {},
    assert: () => {},
  };
} else if (typeof console !== 'undefined') {
  try {
    console.disableYellowBox = true;
  } catch (_) {
    /* Yellow box API may be absent in newer RN */
  }
}

/**
 * Register the root component first so Metro/native always see "CircleApp" even if
 * later bootstrap imports throw during development.
 *
 * @format
 */

import {AppRegistry} from 'react-native';
import {name as appName} from './app.json';

AppRegistry.registerComponent(appName, () => require('./App').default);

require('./index-bootstrap');
